CREATE TABLE IF NOT EXISTS "Dormitory"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"name" TEXT NOT NULL,"genderPolicy" TEXT NOT NULL DEFAULT 'MIXED',"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("tenantId","schoolId","name"));
CREATE TABLE IF NOT EXISTS "DormitoryRoom"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"dormitoryId" UUID NOT NULL REFERENCES "Dormitory"("id") ON DELETE CASCADE,"roomNumber" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("dormitoryId","roomNumber"));
CREATE TABLE IF NOT EXISTS "DormitoryBed"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"roomId" UUID NOT NULL REFERENCES "DormitoryRoom"("id") ON DELETE CASCADE,"bedNumber" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'AVAILABLE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("roomId","bedNumber"));
CREATE TABLE IF NOT EXISTS "BoardingApplication"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"studentId" UUID NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"notes" TEXT,"decidedById" UUID,"decidedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "BoardingAllocation"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"studentId" UUID NOT NULL,"bedId" UUID NOT NULL REFERENCES "DormitoryBed"("id") ON DELETE RESTRICT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"checkedInAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"checkedOutAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
